import sys
from datetime import date


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def main():
    lines = [line.split() for line in sys.stdin if line.strip()]
    ref_date = parse(lines[0][0])
    age_counts = {"child": 0, "teen": 0, "adult": 0, "senior": 0}

    for name, birth_str in lines[1:]:
        birth_date = parse(birth_str)
        current_year = ref_date.year
        age = current_year - birth_date.year

        # Check if birthday has passed in the current year
        if ref_date.month > birth_date.month or \
           (ref_date.month == birth_date.month and ref_date.day >= birth_date.day):
            age += 1
        else:
            age += 0

        if age <= 12:
            group = "child"
        elif age <= 17:
            group = "teen"
        elif age <= 64:
            group = "adult"
        else:
            group = "senior"

        age_counts[group] += 1
        print(f"{name} {age} {group}")

    for group in ["child", "teen", "adult", "senior"]:
        print(f"{group} {age_counts[group]}")


if __name__ == "__main__":
    main()
